import{Base}from"./Base.js";class Handle extends Base{constructor(){super(),this.defaultFrom=()=>[this.parentNode],this.defaultTo=()=>[this.parentNode],this.defaultFor=["blam"]}unString(string){try{return JSON.parse(string)}catch{return"undefined"===string?void 0:string}}setToFrom(){this.fromElems=this.from?[...document.querySelectorAll(this.from)]:this.defaultFrom(),this.toElems=this.to?[...document.querySelectorAll(this.to)]:this.defaultTo()}handleEvent(event){this.for.includes(event.type)&&!this.bypass?this.handle(event):super.handleEvent(event)}listen(){if(this.fromElems?.length&&this.toElems?.length)for(const from of this.fromElems)for(const event of this.for)"any"!==event&&from.addEventListener(event,this)}unlisten(){for(const from of this.fromElems)for(const event of this.for)from.removeEventListener(event,this)}onblamready(){this.setToFrom(),this.listen()}get from(){return this.getAttribute("from")}set from(value){this.setAttribute("from",value)}get to(){return this.getAttribute("to")}set to(value){this.setAttribute("to",value)}get for(){let value=this.getAttribute("for");return value?value.split(" "):this.defaultFor}set for(value){this.setAttribute("for",value)}get prop(){return this.getAttribute("prop")}set prop(value){this.setAttribute("prop",value)}get bypass(){return this.hasAttribute("bypass")}set bypass(value){this.toBoolean("bypass",value)}get chance(){let value=this.getAttribute("chance");return value?parseFloat(value):1}set chance(value){this.setAttribute("chance",value)}disconnectedCallback(){this.unlisten()}}export{Handle};